def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(x for row in grid for x in row), key=lambda x: sum(row.count(x) for row in grid))
    # A pair of colored corner/edge bars indicates vertical guide columns;
    # copy their color through the background between the top and bottom bars.
    for c in range(w):
        if grid[0][c] != bg and grid[-1][c] != bg:
            for r in range(1, h-1):
                if grid[r][c] == bg:
                    out[r][c] = 3
    # Single-color interior markers on that guide are recolored to endpoint 4.
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (bg, 3, 9):
                out[r][c] = 4
    return out

