def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(x for row in grid for x in row), key=lambda x: sum(row.count(x) for row in grid))
    # Border rails define parallel rays inward from their edge. The opposite
    # edge's 9 rail supplies the horizontal axis; preserve the interior 8 dot.
    for r in range(h):
        if grid[r][0] == 9:
            for c in range(w-1):
                if grid[r][c] == 6: out[r][c] = 1
        if grid[r][-1] == 9:
            for c in range(w-1, 0, -1):
                if grid[r][c] == 6: out[r][c] = 1
    # Endpoint accent is placed at the lone marker, with rails continuing
    # through it; the marker itself changes to 4.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8: out[r][c] = 4
    return out

