def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(x for row in grid for x in row), key=lambda x: sum(row.count(x) for row in grid))
    # The isolated 8 is the crossing point of the two guide directions.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8:
                out[r][c] = 8
                for rr in range(h):
                    if rr != r and grid[rr][c] == 6: out[rr][c] = 1
                for cc in range(w):
                    if cc != c and grid[r][cc] == 6: out[r][cc] = 1
    return out

