def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(x for row in grid for x in row), key=lambda x: sum(row.count(x) for row in grid))
    # Edge marker bars project parallel tracks into the field. Tracks follow
    # the marker's color (9 -> 1), the isolated marker becomes 4.
    for r in range(h):
        if grid[r][0] == 9:
            for c in range(1, w):
                if grid[r][c] == 6: out[r][c] = 1
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8: out[r][c] = 4
    return out

